window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[221]={"id":"221","numero":221,"titre":"Athérome — polyathéromateux","objectifs":[{"id":"221-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’athérome","contenu":"<p>L'<span class=\"kw-def\">athérome</span> = <strong>remaniement de l'intima</strong> des <strong>artères de gros et moyen calibre</strong> (aorte et ses branches), défini par une <strong>accumulation focale</strong> de plusieurs constituants.</p>\n      <p>Constituants accumulés dans l'<span class=\"kw-def\">intima</span> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Lipides</span></li>\n        <li><span class=\"kw-def\">Glucides complexes</span></li>\n        <li><span class=\"kw-def\">Sang et produits sanguins</span></li>\n        <li><span class=\"kw-def\">Tissu fibreux</span></li>\n        <li><span class=\"kw-def\">Dépôts calcaires</span></li>\n      </ul>\n      <p>Des modifications de la <span class=\"kw-def\">média</span> peuvent accompagner le remaniement de l'intima.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'<span class=\"kw-etio\">athérome</span> touche les <strong>artères de gros et moyen calibre</strong> — jamais les artérioles ni les capillaires. La <span class=\"kw-clinique\">lésion</span> est <strong>focale</strong> (plaques) et siège dans l'<strong>intima</strong>.\n      </div>","frequence":1},{"id":"221-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition du malade polyathéromateux","contenu":"<p>Le <span class=\"kw-def\">malade polyathéromateux</span> (= polyvasculaire) présente une atteinte athéromateuse d'<strong><span class=\"kw-chiffre\">≥ 2</span> territoires artériels différents</strong>. Chaque atteinte peut être :</p>\n      <ul>\n        <li><strong>Symptomatique</strong> — ex. <span class=\"kw-clinique\">claudication intermittente</span> des membres inférieurs chez un patient aux ATCD d'<span class=\"kw-alerte\">IDM</span></li>\n        <li><strong>Asymptomatique mais significative</strong> — ex. <span class=\"kw-etio\">sténose carotidienne</span> asymptomatique à<span class=\"kw-chiffre\"> 50 %</span> chez un patient porteur d'une AOMI</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Piège classique.</strong> Une simple <span class=\"kw-alerte\">plaque non sténosante (&lt; 50 %)</span> et <strong>non compliquée</strong> ne suffit PAS à qualifier un patient de polyvasculaire — même si elle témoigne d'une <span class=\"kw-etio\">athérosclérose</span> débutante. Il faut une atteinte <strong>significative</strong> (sténose <span class=\"kw-chiffre\">≥ 50 %</span>) ou <strong>symptomatique</strong>.\n      </div>\n      <p>La <span class=\"kw-def\">prévalence</span> du caractère polyvasculaire varie <strong>selon le siège de la 1<sup>re</sup> <span class=\"kw-clinique\">lésion</span> devenue symptomatique</strong> :</p>\n      <table >\n        <thead><tr><th>1<sup>re</sup> lésion symptomatique</th><th>Atteinte d'un autre territoire retrouvée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Patient coronarien</strong></td>\n            <td><span class=\"kw-etio\">AOMI</span> (<span class=\"kw-chiffre\">20 %</span>) ; <span class=\"kw-etio\">sténose carotidienne</span> (<span class=\"kw-chiffre\">20 %</span>) ; <span class=\"kw-etio\">sténose des artères rénales</span> (<span class=\"kw-chiffre\">20 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Patient avec AOMI, sténose carotidienne ou AAA</strong></td>\n            <td>Atteinte <span class=\"kw-clinique\">coronarienne</span> dans <span class=\"kw-chiffre\">40-50 %</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Fréquence des atteintes associées selon la pathologie initiale (en %) :</p>\n      <table >\n        <thead><tr><th>Pathologie du patient</th><th>Coronaires</th><th>AOMI</th><th>Carotides</th><th>AAA</th><th>Artères rénales</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Coronaropathie</strong></td><td>—</td><td><span class=\"kw-chiffre\">19</span></td><td><span class=\"kw-chiffre\">20</span></td><td><span class=\"kw-chiffre\">3</span></td><td><span class=\"kw-chiffre\">18</span></td></tr>\n          <tr><td><strong>AOMI</strong></td><td><span class=\"kw-chiffre\">57</span></td><td>—</td><td><span class=\"kw-chiffre\">15</span></td><td><span class=\"kw-chiffre\">8,5</span></td><td><span class=\"kw-chiffre\">15</span></td></tr>\n          <tr><td><strong>Atteinte des TSA</strong></td><td><span class=\"kw-chiffre\">53</span></td><td><span class=\"kw-chiffre\">35</span></td><td>—</td><td><span class=\"kw-chiffre\">6</span></td><td><span class=\"kw-chiffre\">6</span></td></tr>\n          <tr><td><strong>AAA</strong></td><td><span class=\"kw-chiffre\">53</span></td><td><span class=\"kw-chiffre\">25</span></td><td><span class=\"kw-chiffre\">20</span></td><td>—</td><td><span class=\"kw-chiffre\">28</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Les patients atteints d'<strong>AOMI</strong> sont ceux qui ont le plus souvent une atteinte <strong>polyvasculaire</strong> associée. Toujours rechercher une <span class=\"kw-clinique\">dysfonction érectile</span> : c'est un indicateur sentinelle de maladie artérielle, souvent tu par le patient.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":0},{"id":"221-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence et l’incidence de l’athérome (y compris atteintes infracliniques)","contenu":"<p>L'<span class=\"kw-etio\">athérome</span> débute <strong>très précocement</strong> — les <span class=\"kw-def\">stries lipidiques</span> (premier <span class=\"kw-def\">stade</span> lésionnel) sont retrouvées <strong>dès le jeune âge</strong> sur les autopsies. La maladie évolue ensuite silencieusement pendant des décennies (phase <strong>infraclinique</strong>) avant les premiers accidents.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Tendance</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span> — sexe</strong></td>\n            <td><span class=\"kw-chiffre\">3 à 5 fois</span> plus fréquente chez l'<strong>homme</strong> ; cette différence <strong>s'atténue avec l'âge</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span> — femme</strong></td>\n            <td><span class=\"kw-def\">Incidence</span> des <span class=\"kw-etio\">SCA</span> en <strong>augmentation chez la femme</strong>, par augmentation du <span class=\"kw-etio\">tabagisme</span> féminin</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Mortalité</span> cardiovasculaire</strong></td>\n            <td>Tendance à la <strong>baisse</strong> — progrès de la prise en charge et de la prévention</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span> des maladies CV</strong></td>\n            <td>En <strong>augmentation</strong> — vieillissement des populations + <span class=\"kw-ttt\">réduction</span> de la <span class=\"kw-def\">mortalité</span> (les patients vivent plus longtemps avec la maladie)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span> des maladies CV</strong></td>\n            <td>En <strong>hausse</strong>, tirée par la progression du <span class=\"kw-clinique\">diabète</span> et de l'<span class=\"kw-clinique\">obésité</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Atteintes infracliniques.</strong> Une artère peut s'occlure <strong>progressivement et de façon asymptomatique</strong> grâce au développement d'une <span class=\"kw-clinique\">collatéralité</span> (ex. occlusion chronique d'une coronaire ou de la fémorale superficielle). L'étendue lésionnelle réelle est donc largement sous-estimée par la clinique.\n      </div>","frequence":0},{"id":"221-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes tendances de mortalité et morbidité de la cardiopathie ischémique, l’accident vasculaire cérébral (AVC), l’artériopathie oblitérante des membres inférieurs (AOMI), de l’anévrysme de l’aorte abdominale (causes de mortalité, influence de l’âge et du sexe, évolution dans le temps, gradient nord sud)","contenu":"<p>Les <strong>maladies cardiovasculaires</strong> liées à l'<span class=\"kw-etio\">athérome</span> dominent la <span class=\"kw-def\">mortalité</span> mondiale. Les deux grandes causes de mortalité CV sont la <span class=\"kw-etio\">cardiopathie ischémique</span> et l'<span class=\"kw-etio\">AVC</span>.</p>\n      <table >\n        <thead><tr><th>Échelle</th><th>Place des maladies CV dans la mortalité</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Monde</strong></td><td><span class=\"kw-chiffre\">1<sup>re</sup> cause</span> de <span class=\"kw-def\">mortalité</span></td></tr>\n          <tr><td><strong>France</strong></td><td><span class=\"kw-chiffre\">2<sup>e</sup> cause</span> de <span class=\"kw-def\">mortalité</span>, après le <span class=\"kw-etio\">cancer</span> (forte baisse de la mortalité CV) — mais reste la <strong>1<sup>re</sup> cause chez la femme</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Gradient nord-sud</strong> — la <span class=\"kw-def\">mortalité</span> CV décroît du nord vers le sud :</p>\n      <table >\n        <thead><tr><th>Région</th><th>Mortalité cardiovasculaire</th></tr></thead>\n        <tbody>\n          <tr><td>Pays du <strong>nord et de l'est de l'Europe</strong></td><td>La plus <strong>élevée</strong></td></tr>\n          <tr><td><strong>Amérique du Nord</strong></td><td><strong>Intermédiaire</strong></td></tr>\n          <tr><td><strong>Europe du Sud, Japon</strong></td><td>La plus <strong>faible</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <strong>France</strong> est l'un des pays d'Europe à la <span class=\"kw-def\">mortalité</span> CV la plus faible. Le gradient nord-sud se retrouve <strong>aussi à l'échelle de la France</strong> (gradient intra-national), surtout pour la cardiopathie <span class=\"kw-etio\">ischémique</span>.\n      </div>\n      <p><strong><span class=\"kw-clinique\">Évolution</span> dans le temps</strong> : <strong>diminution</strong> de l'<span class=\"kw-def\">incidence</span> des maladies athéromateuses dans les <strong>pays développés</strong>, mais <strong>augmentation</strong> dans les <strong>pays en voie de développement</strong>. Ces variations sont liées à la <strong>diversité des facteurs environnementaux et des habitudes alimentaires</strong> plutôt qu'à des différences génétiques (ex. risque CV accru chez les migrants asiatiques installés aux USA).</p>\n      <p><strong>Influence de l'âge et du sexe</strong> : nette prédominance masculine, atténuée avec l'âge ; <span class=\"kw-def\">incidence</span> des <span class=\"kw-alerte\">SCA</span> en hausse chez la femme par le <span class=\"kw-etio\">tabagisme</span> (cf. obj-2).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-alerte\">AVC</span> · 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":0},{"id":"221-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de formation et l’évolution de la plaque d’athérome","contenu":"<p><strong>Objectif physiopathologique majeur</strong> (⭐⭐ au QCM). La formation d'une <span class=\"kw-clinique\">plaque</span> suit une <strong>cascade en plusieurs étapes</strong>, débutant par l'accumulation de <span class=\"kw-bio\">LDL</span> dans la paroi artérielle.</p>\n      <p><strong>Formation de la <span class=\"kw-clinique\">plaque</span> — cascade</strong></p>\n      <ol>\n        <li><strong>Dépôt</strong> des lipoprotéines athérogènes dans l'intima — principalement les <span class=\"kw-bio\">LDL</span></li>\n        <li><strong>Oxydation des <span class=\"kw-bio\">LDL</span></strong> dans la paroi, favorisée par un <strong>temps de séjour allongé</strong> et un <strong>environnement <span class=\"kw-etio\">inflammatoire</span> local</strong></li>\n        <li>Les <span class=\"kw-bio\">LDL oxydées</span> ne sont plus reconnues par le récepteur <span class=\"kw-bio\">LDL-R</span></li>\n        <li><strong>Recrutement de macrophages</strong> qui internalisent les <span class=\"kw-bio\">LDL</span> oxydées via les <span class=\"kw-bio\">récepteurs scavengers SR-A</span> (« éboueurs »)</li>\n        <li>Transformation des macrophages en <span class=\"kw-def\">cellules spumeuses</span> (gorgées d'esters de <span class=\"kw-bio\">cholestérol</span>)</li>\n        <li><strong>Dysfonction endothéliale</strong> : baisse des capacités vasodilatatrices et antithrombotiques de l'endothélium, aggravée par le <strong>tabac</strong> et les <span class=\"kw-bio\">LDL</span> oxydées</li>\n        <li><strong>Réaction <span class=\"kw-etio\">inflammatoire</span> auto-entretenue</strong> sécrétant des <span class=\"kw-bio\">métalloprotéases</span> destructrices de la matrice extracellulaire</li>\n        <li><strong>Migration des cellules musculaires lisses</strong> de la média vers la néo-intima</li>\n        <li>Sécrétion de facteurs de croissance, de <span class=\"kw-bio\">collagène</span> et de matrice → organisation de la <span class=\"kw-clinique\">plaque</span></li>\n      </ol>\n      <p>La <span class=\"kw-clinique\">plaque</span> constituée comporte deux composantes :</p>\n      <ul>\n        <li><span class=\"kw-def\">Centre lipidique</span> — nécrotique ; contient stries lipidiques, cellules musculaires lisses et cellules inflammatoires (les stries lipidiques sont retrouvées dès le jeune âge)</li>\n        <li><span class=\"kw-def\">Chape fibreuse</span> — apparition tardive ; recouvre le centre lipidique ; faite de <strong>collagène de type I</strong></li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">Évolution</span> de la <span class=\"kw-clinique\">plaque</span></strong></p>\n      <table >\n        <thead><tr><th>Évolution</th><th>Mécanisme et conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Rupture de plaque</span></td>\n            <td><span class=\"kw-clinique\">Érosion</span> ou déchirure de la chape fibreuse → <strong>formation immédiate d'un <span class=\"kw-alerte\">thrombus</span></strong> → accidents aigus (<span class=\"kw-etio\">SCA</span>, <span class=\"kw-etio\">AVC</span>) par <span class=\"kw-ttt\">réduction</span>/obstruction de la lumière ; le <span class=\"kw-etio\">thrombus</span> peut se fragmenter et donner des <strong>embolies</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Progression de <span class=\"kw-clinique\">plaque</span></strong></td>\n            <td>Augmentation de volume (composante lipidique + matrice) ; progression surtout <strong>par poussées</strong> lors des ruptures (incorporation de matériel <span class=\"kw-etio\">thrombotique</span>) ; une <span class=\"kw-alerte\">hémorragie intraplaque</span> augmente brutalement le volume et peut rompre la chape</td>\n          </tr>\n          <tr>\n            <td><strong>Sténose — remodelage</strong></td>\n            <td><strong>Remodelage compensateur :</strong> le <span class=\"kw-clinique\">diamètre</span> s'élargit pour préserver la lumière artérielle<br><strong>Remodelage constrictif :</strong> le diamètre se réduit et majore la sténose en regard de la <span class=\"kw-clinique\">plaque</span></td>\n          </tr>\n          <tr>\n            <td><strong>Anévrisme</strong></td>\n            <td>L'<span class=\"kw-etio\">athérome</span> peut altérer la structure pariétale et détruire la matrice extracellulaire → <strong>dilatation anévrismale</strong> (mais tous les anévrismes ne sont pas d'origine athéromateuse)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> La <strong>gravité d'un accident aigu n'est pas proportionnelle</strong> à l'ancienneté ni à l'étendue de l'<span class=\"kw-etio\">athérome</span> : la <span class=\"kw-alerte\">rupture</span> d'une <span class=\"kw-clinique\">plaque</span> <strong>jeune</strong> peut causer un <span class=\"kw-clinique\">infarctus</span> ou une <span class=\"kw-alerte\">mort subite</span>, tandis qu'une artère peut s'occlure <strong>sans symptôme</strong> grâce à la collatéralité.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-alerte\">AVC</span></em></p>","frequence":2},{"id":"221-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les particularités de la physiopathologie de l’athérome (cibles et intervenants)","contenu":"<p>La <span class=\"kw-def\">physiopathologie</span> de l'<span class=\"kw-etio\">athérome</span> met en jeu des <strong>intervenants</strong> cellulaires et moléculaires précis ; chacun constitue une <strong>cible thérapeutique</strong> potentielle.</p>\n      <p><strong>Intervenants de l'athérogenèse</strong></p>\n      <table >\n        <thead><tr><th>Intervenant</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">LDL</span> / <span class=\"kw-bio\">LDL</span> oxydées</td><td>Lipoprotéines athérogènes ; substrat initial de la <span class=\"kw-clinique\">plaque</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Macrophages</span> → cellules spumeuses</td><td>Internalisent les <span class=\"kw-bio\">LDL</span> oxydées (récepteurs scavengers SR-A) ; entretiennent l'inflammation</td></tr>\n          <tr><td><span class=\"kw-def\">Endothélium</span></td><td>Sa dysfonction (perte des propriétés vasodilatatrices et antithrombotiques) initie et entretient la <span class=\"kw-clinique\">lésion</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Cellules musculaires lisses</span></td><td>Migrent de la média vers l'intima ; synthétisent collagène et matrice (chape fibreuse)</td></tr>\n          <tr><td><span class=\"kw-bio\">Métalloprotéases</span> et inflammation</td><td>Détruisent la matrice extracellulaire ; fragilisent la chape → risque de <span class=\"kw-alerte\">rupture</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cibles thérapeutiques — points d'impact des traitements</strong></p>\n      <table >\n        <thead><tr><th>Cible</th><th>Moyen d'action</th></tr></thead>\n        <tbody>\n          <tr><td>Dysfonction endothéliale</td><td>Suppression / traitement de <strong>tous les <span class=\"kw-def\">facteurs de risque</span> modifiables</strong></td></tr>\n          <tr><td>Accumulation des <span class=\"kw-bio\">LDL</span></td><td>Régime alimentaire ; <span class=\"kw-ttt\">statines</span> et autres hypolipémiants</td></tr>\n          <tr><td>Stabilisation des plaques</td><td>Diminuer le risque de <span class=\"kw-alerte\">rupture</span> — propriété propre des <span class=\"kw-ttt\">statines</span></td></tr>\n          <tr><td>Régression du volume de <span class=\"kw-clinique\">plaque</span></td><td><span class=\"kw-ttt\">Statines à forte dose</span>, si besoin associées à l'<span class=\"kw-ttt\">ézétimibe</span> ou aux <span class=\"kw-ttt\">anti-PCSK9</span></td></tr>\n          <tr><td>Inflammation</td><td><span class=\"kw-ttt\">Aspirine</span> ; <span class=\"kw-ttt\">statines</span></td></tr>\n          <tr><td>Contraintes mécaniques</td><td>Traitements <span class=\"kw-ttt\">antihypertenseurs</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les <span class=\"kw-ttt\">statines</span> agissent sur <strong>plusieurs cibles à la fois</strong> : baisse des <span class=\"kw-bio\">LDL</span>, stabilisation de la <span class=\"kw-clinique\">plaque</span>, régression du volume, effet anti-<span class=\"kw-etio\">inflammatoire</span> — d'où leur place centrale.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 223 — <span class=\"kw-etio\">Dyslipidémie</span></em></p>","frequence":0},{"id":"221-7","rang":"A","rubrique":"Diagnostic","titre":"Connaître les localisations préférentielles de la maladie athéromateuse","contenu":"<p>L'<span class=\"kw-etio\">athérome</span> touche les <strong>artères de gros et moyen calibre</strong> (aorte et ses branches). Les plaques se forment préférentiellement à proximité des <strong>flux artériels turbulents</strong> : <span class=\"kw-clinique\">ostiums</span>, <span class=\"kw-clinique\">bifurcations</span>, zones de <span class=\"kw-clinique\">contrainte mécanique</span>.</p>\n      <p>Six localisations principales, classées par fréquence et conséquences pathologiques :</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Conséquence clinique</th></tr></thead>\n        <tbody>\n          <tr><td>1 · Artères <strong>carotidiennes</strong></td><td><span class=\"kw-etio\">AVC</span></td></tr>\n          <tr><td>2 · Artères <strong>coronariennes</strong></td><td><span class=\"kw-etio\">Cardiopathies ischémiques</span></td></tr>\n          <tr><td>3 · <strong>Crosse de l'aorte</strong></td><td><span class=\"kw-etio\">AVC</span> ; <span class=\"kw-etio\">anévrisme de l'aorte abdominale</span></td></tr>\n          <tr><td>4 · Artères <strong>rénales</strong></td><td><span class=\"kw-etio\">HTA</span> ; <span class=\"kw-etio\">insuffisance rénale</span> (néphropathie vasculaire)</td></tr>\n          <tr><td>5 · Artères <strong>digestives</strong></td><td><span class=\"kw-etio\">Ischémie mésentérique</span></td></tr>\n          <tr><td>6 · Artères des <strong>membres inférieurs</strong></td><td><span class=\"kw-etio\">Artériopathie oblitérante (AOMI)</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les réductions successives de lumière donnent une <strong>ischémie chronique stable</strong> (<span class=\"kw-clinique\">angor</span> d'effort, <span class=\"kw-clinique\">claudication</span> intermittente, claudication digestive postprandiale). Les ruptures de <span class=\"kw-clinique\">plaque</span> donnent des <strong>accidents aigus</strong> dépendant du territoire (<span class=\"kw-alerte\">SCA</span>, <span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span>, <span class=\"kw-alerte\">ischémie aiguë</span> de membre).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-alerte\">AVC</span> · 224 — <span class=\"kw-etio\">HTA</span> · 225 — Artériopathie oblitérante - anévrysme · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":0},{"id":"221-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration en imagerie devant une maladie athéromateuse","contenu":"<p>Devant une maladie athéromateuse, le <span class=\"kw-def\">bilan d'extension</span> repose sur un <strong>examen clinique systématique de tous les territoires artériels</strong>, complété par des examens paracliniques hiérarchisés.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">ECG</span></td><td>Systématique</td></tr>\n          <tr><td><span class=\"kw-imagerie\">IPS</span> (<span class=\"kw-imagerie\">index de pression systolique</span>)</td><td>Systématique — <span class=\"kw-def\">dépistage</span> de l'<span class=\"kw-etio\">AOMI</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie de l'aorte abdominale</span></td><td><span class=\"kw-def\">Dépistage</span> de l'<span class=\"kw-etio\">anévrisme de l'aorte abdominale</span>, notamment chez l'<strong>homme &gt; <span class=\"kw-chiffre\">65 ans</span></strong></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie-doppler des TSA</span> (troncs supra-aortiques)</td><td>Systématique selon l'avis de <span class=\"kw-ttt\">chirurgie</span> vasculaire</td></tr>\n          <tr><td><strong>Autres explorations</strong></td><td>Au cas par cas, selon la clinique, le risque CV global, la <span class=\"kw-def\">prévalence</span> d'atteinte d'un autre territoire et la nécessité d'un geste invasif</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Les fiches sources du dossier <code>221-atherome/</code> détaillent surtout le <span class=\"kw-def\">bilan d'extension</span> du polyathéromateux (<span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-imagerie\">IPS</span>, échographies). La stratégie d'imagerie fine par territoire (<span class=\"kw-def\">score</span> calcique, <span class=\"kw-imagerie\">angio-TDM</span> coronaire, <span class=\"kw-imagerie\">IRM</span> / <span class=\"kw-imagerie\">angio-TDM</span> aortique, <span class=\"kw-imagerie\">écho-doppler</span> artériel des membres inférieurs, FFR…) n'y figure pas — à enrichir manuellement depuis le Collège de cardiologie / médecine vasculaire.\n      </div>","frequence":0},{"id":"221-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge du malade polyathéromateux","contenu":"<p><strong>Objectif majeur</strong> (⭐⭐ au QCM). La prise en charge associe un <strong><span class=\"kw-def\">bilan d'extension</span></strong>, un <strong>traitement médical commun à tous les territoires</strong> et le traitement des <strong>lésions les plus menaçantes</strong>.</p>\n      <p><strong>1 · Bilan du polyathéromateux</strong></p>\n      <ul>\n        <li>Prise en charge des <strong><span class=\"kw-def\">facteurs de risque</span></strong>, commune à tous les territoires atteints</li>\n        <li>Calcul du <strong>risque cardiovasculaire global</strong></li>\n        <li><strong><span class=\"kw-def\">Bilan d'extension</span></strong> : bilan clinique systématique de tous les territoires + bilan paraclinique (<span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-imagerie\">IPS</span>, <span class=\"kw-def\">dépistage</span> de l'AAA, <span class=\"kw-imagerie\">écho-doppler</span> des TSA — cf. obj-7)</li>\n      </ul>\n      <p><strong>2 · Traitement médical</strong></p>\n      <table >\n        <thead><tr><th>Traitement</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Aspirine</span> (<span class=\"kw-chiffre\">75-325 mg/j</span>)</td><td><strong>Systématique</strong> ; <span class=\"kw-ci\">contre-indications</span> rares (<span class=\"kw-ci\">intolérance gastrique</span>, <span class=\"kw-ci\">allergie</span>)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Clopidogrel</span></td><td>Si <span class=\"kw-ci\">intolérance à l'aspirine</span>, ou atteinte polyvasculaire compliquée (notamment AOMI)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Statines</span></td><td><strong>Systématiques</strong>, avec les objectifs d'une <strong><span class=\"kw-def\">prévention secondaire</span></strong></td></tr>\n          <tr><td><span class=\"kw-ttt\">IEC / ARA2</span></td><td>Recommandés — réduisent le risque d'<span class=\"kw-clinique\">infarctus</span> et d'<span class=\"kw-alerte\">AVC</span>, freinent l'altération de la fonction rénale</td></tr>\n          <tr><td><span class=\"kw-ttt\">β-bloquants</span></td><td>Efficacité prouvée <strong>uniquement après un <span class=\"kw-alerte\">infarctus du myocarde</span></strong></td></tr>\n        </tbody>\n      </table>\n      <p>Mesures non médicamenteuses systématiques : <strong>arrêt du tabac</strong>, <span class=\"kw-ttt\">règles hygiéno-diététiques</span>, activité physique, <span class=\"kw-def\">éducation thérapeutique</span> (cf. obj-9).</p>\n      <div class=\"callout callout-info\"><strong>📌 Précisions LiSA.</strong>\n        <ul>\n          <li><strong>Régime <span class=\"kw-ttt\">méditerranéen</span></strong> : privilégier <span class=\"kw-clinique\">poissons ≥ 3×/semaine</span>, fruits, légumes, <span class=\"kw-ttt\">huiles d'olive et de colza</span> (acides gras poly- et mono-insaturés) ; réduire sel, sucres libres et alcool.</li>\n          <li><strong><span class=\"kw-clinique\">Activité physique</span> ≥ <span class=\"kw-chiffre\">150 min/semaine</span></strong> d'intensité modérée (marche, vélo, natation ; <span class=\"kw-chiffre\">30 min × 5 j/sem</span>). En cas d'<span class=\"kw-etio\">AOMI</span>, la marche est l'activité de <strong>1ʳᵉ intention</strong> (développe la collatéralité).</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Les <span class=\"kw-ttt\">β-bloquants</span> n'ont <strong>pas</strong> démontré d'efficacité dans la maladie coronarienne stable ni chez le malade polyvasculaire — leur bénéfice est établi <strong>seulement après un <span class=\"kw-alerte\">IDM</span></strong>.\n      </div>\n      <p><strong>3 · Traitement des localisations</strong> (s'apparente à de la <span class=\"kw-def\">prévention secondaire</span>)</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Indication de geste</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Anévrisme de l'aorte abdominale</span></td>\n            <td><span class=\"kw-ttt\">Chirurgie</span> si <span class=\"kw-chiffre\">≥ 50-55 mm</span>, ou croissance <span class=\"kw-chiffre\">≥ 1 cm/an</span>, ou anévrisme <strong>compliqué</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Sténose carotidienne</span> — endartériectomie</td>\n            <td><strong>Asymptomatique</strong> (<span class=\"kw-def\">prévention primaire</span>) : sténose <span class=\"kw-chiffre\">&gt; 60 %</span> et espérance de vie <span class=\"kw-chiffre\">&gt; 5 ans</span><br><strong>Après <span class=\"kw-alerte\">AVC</span></strong> (<span class=\"kw-def\">prévention secondaire</span>) : sténose <span class=\"kw-chiffre\">&gt; 70 %</span> ; indication discutée entre <span class=\"kw-chiffre\">50-70 %</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Revascularisation myocardique</span></td>\n            <td><strong>Après <span class=\"kw-alerte\">SCA</span></strong> : systématique si sténose significative (<span class=\"kw-chiffre\">&gt; 50 %</span> du tronc commun ou <span class=\"kw-chiffre\">&gt; 70 %</span> ailleurs)<br><strong>Ischémie silencieuse / <span class=\"kw-clinique\">angor</span> stable</strong> : si symptômes persistants malgré traitement, <span class=\"kw-ttt\">chirurgie</span> à haut risque, <span class=\"kw-alerte\">FEVG altérée</span>, faible seuil d'ischémie, ischémie étendue documentée, ou <span class=\"kw-chiffre\">FFR ≤ 0,8</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-def\">Suivi</span> : <strong>examen clinique annuel</strong> ; explorations complémentaires au cas par cas.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 224 — HTA · 225 — Artériopathie oblitérante - anévrysme · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":2},{"id":"221-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de l’éducation thérapeutique du patient athéromateux","contenu":"<p>L'<span class=\"kw-def\">éducation thérapeutique</span> du patient <span class=\"kw-etio\">athéromateux</span> fait partie intégrante des moyens thérapeutiques, au même titre que le traitement <span class=\"kw-etio\">médicamenteux</span>. Elle vise à rendre le patient acteur du contrôle de sa maladie au long cours.</p>\n      <p>Axes principaux issus des fiches sources :</p>\n      <ul>\n        <li><strong>Arrêt du tabac</strong> — mesure prioritaire et systématique</li>\n        <li><strong><span class=\"kw-ttt\">Règles hygiéno-diététiques</span></strong> — alimentation, contrôle pondéral</li>\n        <li><strong>Activité physique</strong> régulière</li>\n        <li><strong>Contrôle des <span class=\"kw-def\">facteurs de risque</span></strong> modifiables, commun à tous les territoires atteints</li>\n        <li><strong>Observance</strong> du traitement de <span class=\"kw-def\">prévention secondaire</span> (<span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">statine</span>, <span class=\"kw-ttt\">IEC/ARA2</span>)</li>\n        <li><strong><span class=\"kw-def\">Suivi</span></strong> : examen clinique <strong>annuel</strong>, explorations complémentaires au cas par cas</li>\n        <li><strong><span class=\"kw-ttt\">Entretiens motivationnels</span> répétés</strong> — outil-clé LiSA pour obtenir et maintenir les changements de mode de vie (sevrage tabagique, alimentation, activité physique) et vérifier l'adhésion aux traitements</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Reconnaître les signes d'appel des complications.</strong> Le patient doit savoir repérer les signes d'alerte imposant une <strong>consultation en <span class=\"kw-alerte\">urgence</span></strong> :\n        <ul>\n          <li><span class=\"kw-alerte\">Douleur thoracique</span> → suspicion de <span class=\"kw-etio\">SCA</span></li>\n          <li><span class=\"kw-alerte\">Déficit neurologique brutal</span> → suspicion d'<span class=\"kw-etio\">AVC</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 223 — <span class=\"kw-etio\">Dyslipidémie</span></em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p>La PEC du <span class=\"kw-def\">malade polyathéromateux</span> est <strong>commune à tous les territoires</strong> : contrôle des <span class=\"kw-etio\">facteurs de risque</span> + traitement médical de <strong><span class=\"kw-def\">prévention secondaire</span></strong> (<span class=\"kw-ttt\">antiplaquettaire</span> + <span class=\"kw-ttt\">statine</span> + <span class=\"kw-ttt\">IEC/ARA2</span>) + traitement des <strong>lésions les plus menaçantes</strong>.</p><p><strong>Bilan & contrôle des <span class=\"kw-def\">facteurs de risque</span></strong></p><p>Mesures systématiques : <span class=\"kw-ttt\">arrêt du tabac</span>, <span class=\"kw-ttt\">règles hygiéno-diététiques</span>, <span class=\"kw-ttt\">activité physique</span>, <span class=\"kw-def\">éducation thérapeutique</span></p><ul><li>Prise en charge des <span class=\"kw-etio\">facteurs de risque</span> commune à tous les territoires atteints</li><li>Calcul du <span class=\"kw-def\">risque cardiovasculaire global</span></li><li><span class=\"kw-def\">Bilan d'extension</span> clinique systématique de tous les territoires</li><li>Bilan paraclinique : <span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-imagerie\">IPS</span>, <span class=\"kw-def\">dépistage</span> de l'<span class=\"kw-etio\">AAA</span> (homme &gt; <span class=\"kw-chiffre\">65 ans</span>), <span class=\"kw-imagerie\">écho-doppler des TSA</span></li></ul><p><strong>Traitement médical de fond</strong></p><p><span class=\"kw-ci\">β-bloquants sans bénéfice démontré hors post-IDM</span> (ni dans la coronaropathie stable, ni chez le polyvasculaire)</p><ul><li><span class=\"kw-ttt\">Aspirine</span> (<span class=\"kw-chiffre\">75-325 mg/j</span>) : systématique — CI rares (<span class=\"kw-ci\">intolérance gastrique</span>, <span class=\"kw-ci\">allergie</span>)</li><li><span class=\"kw-ttt\">Clopidogrel</span> si <span class=\"kw-ci\">intolérance à l'aspirine</span> ou atteinte polyvasculaire compliquée (notamment AOMI)</li><li><span class=\"kw-ttt\">Statines</span> : systématiques, avec les objectifs d'une <strong><span class=\"kw-def\">prévention secondaire</span></strong></li><li><span class=\"kw-ttt\">IEC / ARA2</span> : recommandés — réduisent le risque d'<span class=\"kw-clinique\">infarctus</span> et d'<span class=\"kw-etio\">AVC</span>, freinent l'altération rénale</li><li><span class=\"kw-ttt\">β-bloquants</span> : efficacité prouvée <strong>uniquement après un <span class=\"kw-alerte\">infarctus du myocarde</span></strong></li></ul><p><strong>Traitement des localisations <span class=\"q\">— <span class=\"kw-def\">prévention secondaire</span></span></strong></p><p><span class=\"kw-ttt\">Revascularisation</span> dans l'<span class=\"kw-clinique\">angor</span> stable / ischémie silencieuse si <span class=\"kw-alerte\">FEVG altérée</span>, ischémie étendue documentée, ou <span class=\"kw-chiffre\">FFR ≤ 0,8</span></p><ul><li><span class=\"kw-etio\">Anévrisme de l'aorte abdominale</span> : <span class=\"kw-ttt\">chirurgie</span> si <span class=\"kw-chiffre\">≥ 50-55 mm</span>, croissance <span class=\"kw-chiffre\">≥ 1 cm/an</span>, ou <span class=\"kw-alerte\">compliqué</span></li><li><span class=\"kw-ttt\">Endartériectomie carotidienne</span> asymptomatique : sténose <span class=\"kw-chiffre\">&gt; 60 %</span> + espérance de vie <span class=\"kw-chiffre\">&gt; 5 ans</span></li><li><span class=\"kw-ttt\">Endartériectomie carotidienne</span> après <span class=\"kw-etio\">AVC</span> : sténose <span class=\"kw-chiffre\">&gt; 70 %</span> (indication discutée entre <span class=\"kw-chiffre\">50-70 %</span>)</li><li><span class=\"kw-ttt\">Revascularisation myocardique</span> après <span class=\"kw-etio\">SCA</span> : si sténose <span class=\"kw-chiffre\">&gt; 50 %</span> du tronc commun ou <span class=\"kw-chiffre\">&gt; 70 %</span> ailleurs</li></ul>","suivi":"<p><strong>Rythme :</strong> <span class=\"kw-clinique\">examen clinique annuel</span> ; explorations complémentaires au cas par cas.<br><strong><span class=\"kw-def\">Éducation thérapeutique</span> :</strong> <span class=\"kw-ttt\">arrêt du tabac</span> (prioritaire), <span class=\"kw-ttt\">règles hygiéno-diététiques</span>, <span class=\"kw-ttt\">activité physique</span> régulière, contrôle des <span class=\"kw-etio\">facteurs de risque</span> modifiables, observance du traitement (<span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">statine</span>, <span class=\"kw-ttt\">IEC/ARA2</span>).<br><strong>Auto-<span class=\"kw-def\">surveillance</span> :</strong> le patient doit savoir reconnaître les signes d'appel imposant une consultation en <span class=\"kw-alerte\">urgence</span> (cf. <span class=\"kw-alerte\">red flags</span>).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Douleur thoracique</span> brutale → suspicion de <span class=\"kw-etio\">SCA</span> (thrombose coronaire occlusive)</li><li><span class=\"kw-alerte\">Déficit neurologique brutal</span> → suspicion d'<span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">ischémique</span></li><li><span class=\"kw-alerte\">Ischémie aiguë de membre</span> (douleur, froideur, abolition de pouls) → <span class=\"kw-alerte\">urgence</span> de <span class=\"kw-ttt\">revascularisation</span></li><li><span class=\"kw-alerte\">Anévrisme de l'aorte abdominale compliqué</span> ou symptomatique → risque de <span class=\"kw-alerte\">rupture</span>, indication chirurgicale</li><li><span class=\"kw-clinique\">Dysfonction érectile</span> → indicateur sentinelle de maladie artérielle, à rechercher systématiquement</li></ul>"},"liensGlobaux":[{"href":"https://ressources.unisciel.fr/physiologie/co/act1_Parois_arterielles_veineuses_1.html","label":"Act1 parois arterielles veineuses 1"}],"cards":[{"i":"286f60f2bd36","n":221,"o":"221-1","u":"Définition","t":"Connaître la définition de l’athérome","q":"Quelle est la définition de l'athérome ?","a":"<p>L'athérome est un <strong>remaniement de l'intima</strong> des artères de <strong>gros et moyen calibre</strong> (aorte et ses branches), défini par une <strong>accumulation focale</strong> de plusieurs constituants.</p>"},{"i":"ca6a242a9dc7","n":221,"o":"221-1","u":"Définition","t":"Connaître la définition de l’athérome","q":"Quelles sont les caractéristiques principales de la localisation de l'athérome ?","a":"<ul><li>Il touche les artères de <strong>gros et moyen calibre</strong>, <strong>jamais les artérioles ni les capillaires</strong>.</li><li>La lésion est <strong>focale</strong> (plaques).</li><li>Elle siège dans l'<strong>intima</strong>.</li></ul>"},{"i":"eca9817e28e8","n":221,"o":"221-1","u":"Définition","t":"Connaître la définition de l’athérome","q":"Quels sont les constituants accumulés dans l'intima lors de l'athérome ?","a":"<ul><li><strong>Lipides</strong></li><li><strong>Glucides complexes</strong></li><li><strong>Sang et produits sanguins</strong></li><li><strong>Tissu fibreux</strong></li><li><strong>Dépôts calcaires</strong></li></ul>"},{"i":"0700b43729ea","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Chez quel type de patient doit-on particulièrement rechercher une atteinte polyvasculaire associée ?","a":"<p>Les patients atteints d'<strong>artériopathie oblitérante des membres inférieurs (AOMI)</strong> sont ceux qui présentent le plus souvent une atteinte polyvasculaire associée.</p>"},{"i":"4fe465b59bb2","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Quelle est la définition d'un malade polyathéromateux ?","a":"<p>Un malade polyathéromateux, également appelé polyvasculaire, est un patient qui présente une <strong>atteinte athéromateuse d'au moins deux territoires artériels différents</strong>.</p>"},{"i":"9b4dadf0a1d0","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Quel signe clinique spécifique doit être recherché systématiquement chez un patient avec de l'athérosclérose, même s'il est souvent tu ?","a":"<p>Il faut toujours rechercher une <strong>dysfonction érectile</strong>, car c'est un indicateur sentinelle de maladie artérielle, souvent non rapporté spontanément par le patient.</p>"},{"i":"9e8343668410","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Comment caractérise-t-on une atteinte artérielle pour définir un patient comme polyvasculaire ?","a":"<ul><li>L'atteinte peut être <strong>symptomatique</strong> (par exemple, une claudication intermittente des membres inférieurs).</li><li>Elle peut être <strong>asymptomatique mais significative</strong>, ce qui correspond à une sténose d'au moins <strong>50%</strong>.</li></ul>"},{"i":"d2e8b35cde8e","n":221,"o":"221-2","u":"Définition","t":"Connaître la définition du malade polyathéromateux","q":"Qu'est-ce qui ne suffit pas à qualifier un patient de polyvasculaire ?","a":"<p>La présence d'une simple <strong>plaque non sténosante (< 50%)</strong> et non compliquée ne suffit pas à qualifier un patient de polyvasculaire, même si elle témoigne d'une athérosclérose débutante. Il faut une atteinte significative (sténose ≥ 50%) ou symptomatique.</p>"},{"i":"429009706349","n":221,"o":"221-7","u":"Diagnostic","t":"Connaître les localisations préférentielles de la maladie athéromateuse","q":"Quelles sont les six localisations principales de la maladie athéromateuse et leurs conséquences cliniques associées ?","a":"<p>Les six localisations principales de la maladie athéromateuse et leurs conséquences cliniques sont :</p><ul><li><strong>Artères carotidiennes</strong> : Accident Vasculaire Cérébral (AVC).</li><li><strong>Artères coronariennes</strong> : Cardiopathies ischémiques (Syndrome Coronaire Aigu - SCA).</li><li><strong>Crosse de l'aorte</strong> : AVC ou anévrisme de l'aorte abdominale.</li><li><strong>Artères rénales</strong> : Hypertension Artérielle (HTA) ou insuffisance rénale (néphropathie vasculaire).</li><li><strong>Artères digestives</strong> : Ischémie mésentérique.</li><li><strong>Artères des membres inférieurs</strong> : Artériopathie Oblitérente des Membres Inférieurs (AOMI).</li></ul>"},{"i":"a08cc6aed7a7","n":221,"o":"221-7","u":"Diagnostic","t":"Connaître les localisations préférentielles de la maladie athéromateuse","q":"Où se forment préférentiellement les plaques d'athérome ?","a":"<p>Les plaques d'athérome se forment préférentiellement dans les zones de <strong>flux artériels turbulents</strong>, telles que :</p><ul><li>Les <strong>ostiums</strong>.</li><li>Les <strong>bifurcations</strong>.</li><li>Les zones de forte <strong>contrainte mécanique</strong>.</li></ul>"},{"i":"b094c501eef2","n":221,"o":"221-7","u":"Diagnostic","t":"Connaître les localisations préférentielles de la maladie athéromateuse","q":"Quels types d'artères sont principalement touchés par la maladie athéromateuse ?","a":"<p>La maladie athéromateuse touche préférentiellement les <strong>artères de gros et moyen calibre</strong>, notamment <strong>l'aorte et ses branches</strong>.</p>"},{"i":"254dceb83828","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quelles sont les indications chirurgicales ou d'endartériectomie pour une sténose carotidienne chez un patient polyathéromateux ?","a":"<p>Pour une sténose carotidienne, les indications de geste sont :</p><ul><li><strong>Asymptomatique (prévention primaire)</strong> : si sténose <strong>> 60 %</strong> et espérance de vie <strong>> 5 ans</strong>.</li><li><strong>Après un AVC (prévention secondaire)</strong> : si sténose <strong>> 70 %</strong> ; l'indication est discutée entre 50-70 %.</li></ul>"},{"i":"36d48eb8ea28","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quel est l'objectif majeur de la prise en charge d'un patient polyathéromateux ?","a":"<p>L'objectif majeur est triple :</p><ul><li>Un <strong>bilan d'extension</strong> pour identifier toutes les localisations de l'athérome.</li><li>Un <strong>traitement médical commun</strong> ciblant les facteurs de risque et freinat la progression de la maladie.</li><li>Le <strong>traitement des lésions les plus menaçantes</strong>, spécifique à chaque territoire.</li></ul>"},{"i":"5377f4ecfbb1","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quelles sont les mesures non médicamenteuses systématiques dans la prise en charge du patient polyathéromateux ?","a":"<p>Les mesures non médicamenteuses systématiques incluent :</p><ul><li>L'<strong>arrêt du tabac</strong>.</li><li>Le respect de <strong>règles hygiéno-diététiques</strong>.</li><li>La pratique d'une <strong>activité physique régulière</strong>.</li><li>Une <strong>éducation thérapeutique</strong> du patient.</li></ul>"},{"i":"57d034799c8f","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quelle est la place des bêta-bloquants dans la prise en charge du patient polyathéromateux ?","a":"<p>Les <strong>bêta-bloquants</strong> ont une efficacité prouvée <strong>uniquement après un infarctus du myocarde</strong>. Ils n'ont pas démontré de bénéfice dans la maladie coronarienne stable ni chez le malade polyvasculaire en dehors de ce contexte.</p>"},{"i":"ab31c4f75533","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Quels sont les traitements médicamenteux obligatoires ou systématiques chez un patient polyathéromateux ?","a":"<p>Les traitements médicamenteux systématiques incluent :</p><ul><li>L'<strong>aspirine</strong> (75-325 mg/j), sauf contre-indication (intolérance gastrique, allergie).</li><li>Les <strong>statines</strong>, avec les objectifs d'une prévention secondaire.</li><li>Les <strong>IEC/ARA2</strong> (Inhibiteurs de l'Enzyme de Conversion/Antagonistes des Récepteurs de l'Angiotensine II) sont recommandés.</li></ul><p>Le <strong>Clopidogrel</strong> est utilisé si intolérance à l'aspirine ou atteinte polyvasculaire compliquée (notamment AOMI).</p>"},{"i":"d722aeb150be","n":221,"o":"221-9","u":"Prise en charge","t":"Connaître les principes de prise en charge du malade polyathéromateux","q":"Comment évalue-t-on l'extension de l'athérosclérose chez un patient polyathéromateux ?","a":"<p>Le bilan d'extension comprend :</p><ul><li>Un <strong>bilan clinique systématique</strong> de tous les territoires vasculaires.</li><li>Un <strong>bilan paraclinique</strong> incluant un <strong>ECG</strong>, la mesure de l'<strong>IPS</strong> (Index de Pression Systolique), le dépistage d'un <strong>AAA</strong> (Anévrisme de l'Aorte Abdominale), et un <strong>écho-Doppler des TSA</strong> (Troncs Supra-Aortiques).</li></ul>"}]};